CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `passwordHash` VARCHAR(255) NOT NULL, `role` VARCHAR(20) NOT NULL DEFAULT 'MEMBER', `accountSlot` TINYINT UNSIGNED NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `User_email_key`(`email`), UNIQUE INDEX `User_accountSlot_key`(`accountSlot`), PRIMARY KEY (`id`), CONSTRAINT `User_accountSlot_range` CHECK (`accountSlot` BETWEEN 1 AND 5)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Source` (`id` VARCHAR(60) NOT NULL, `name` VARCHAR(120) NOT NULL, `baseUrl` VARCHAR(500) NOT NULL, `licensePolicy` TEXT NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT true, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Book` (`id` VARCHAR(191) NOT NULL, `source` VARCHAR(60) NOT NULL, `sourceUrl` VARCHAR(1000) NOT NULL, `title` VARCHAR(1000) NOT NULL, `authors` TEXT NOT NULL, `description` TEXT NULL, `coverUrl` VARCHAR(1000) NULL, `language` VARCHAR(50) NOT NULL, `year` INTEGER NULL, `license` VARCHAR(255) NOT NULL, `rightsBasis` TEXT NOT NULL, `countryRestrictions` TEXT NOT NULL, `attribution` TEXT NOT NULL, `formats` TEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `Book_title_idx`(`title`(191)), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Favorite` (`userId` VARCHAR(191) NOT NULL, `bookId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`userId`,`bookId`), CONSTRAINT `Favorite_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `Favorite_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SavedBook` (`userId` VARCHAR(191) NOT NULL, `bookId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`userId`,`bookId`), CONSTRAINT `SavedBook_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `SavedBook_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ReadingProgress` (`userId` VARCHAR(191) NOT NULL, `bookId` VARCHAR(191) NOT NULL, `locator` TEXT NOT NULL, `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`userId`,`bookId`), CONSTRAINT `ReadingProgress_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `ReadingProgress_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Bookmark` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `bookId` VARCHAR(191) NOT NULL, `locator` TEXT NOT NULL, `label` VARCHAR(255) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `Bookmark_userId_bookId_idx`(`userId`,`bookId`), PRIMARY KEY (`id`), CONSTRAINT `Bookmark_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `Bookmark_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `UserSettings` (`userId` VARCHAR(191) NOT NULL, `theme` VARCHAR(20) NOT NULL DEFAULT 'light', `fontSize` INTEGER NOT NULL DEFAULT 18, `readingLanguage` VARCHAR(20) NOT NULL DEFAULT 'en', `translationLanguage` VARCHAR(20) NOT NULL DEFAULT 'ta', PRIMARY KEY (`userId`), CONSTRAINT `UserSettings_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ApiCache` (`key` VARCHAR(512) NOT NULL, `value` LONGTEXT NOT NULL, `expiresAt` DATETIME(3) NOT NULL, INDEX `ApiCache_expiresAt_idx`(`expiresAt`), PRIMARY KEY (`key`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT INTO `Source` (`id`,`name`,`baseUrl`,`licensePolicy`) VALUES ('gutenberg','Project Gutenberg','https://www.gutenberg.org/','Gutendex copyright=false and readable formats; verify edition terms and territorial status'),('wikisource','Wikisource','https://www.wikisource.org/','Page-specific public domain or CC BY-SA; check original page license and attribution');
